info.description:
Changes chrome to UMD colors@-moz-document domain("google.com") {
  body {
    background-color: #e21833 !important; /* UMD red */
    color: #ffffff !important;
    font-family: "Helvetica Neue", sans-serif !important;
  }

  input[type="text"] {
    background-color: #ffffff !important;
    border: 2px solid #ffcc00 !important; /* UMD gold */
    color: #000000 !important;
    padding: 10px !important;
    border-radius: 6px !important;
  }

  input[type="submit"],
  .gb_d,
  .gb_e {
    background-color: #000000 !important;
    color: #ffcc00 !important;
    border: none !important;
    border-radius: 4px !important;
    padding: 6px 12px !important;
    font-weight: bold !important;
  }

  a {
    color: #ffcc00 !important;
  }

  /* Google logo fade-out (optional) */
  img[alt="Google"] {
    filter: hue-rotate(10deg) saturate(0) brightness(1.5);
    opacity: 0.8;
  }
}

